\begin{tikzpicture}[font=\sffamily, scale=1.0]
  % Colors and styles
  \tikzstyle{electrode}=[fill=gray!70, draw=black, thick]
  \tikzstyle{wire}=[thick]

  % --- Beaker ---
  \draw[thick] (0, 0) arc (180:360:2.5 and 0.6) -- (5, 4) arc (360:180:2.5 and 0.6) -- cycle;
  \draw[thick] (0, 4) ellipse (2.5 and 0.6);

  % --- Solution ---
  \dotregion{0.2}{0.4}{4.8}{2.8}
  \node at (2.5, 1.8) [align=center, font=\sffamily\small] {dilute sodium\\chloride solution};

  % --- Electrodes coming through the bottom ---
  % Left electrode (Anode)
  \draw[electrode] (1.3, -0.4) rectangle (1.7, 1.8);
  % Right electrode (Cathode)
  \draw[electrode] (3.3, -0.4) rectangle (3.7, 1.8);

  % --- Inverted Test Tubes ---
  % Left test tube (over anode)
  \draw[thick] (0.8, 4.2) -- (0.8, 1.5) arc (180:360:0.7 and 0.2) -- (2.2, 4.2);
  % Left tube liquid level (higher liquid = less gas)
  \dotregion{0.81}{1.5}{2.19}{2.4}

  % Right test tube (over cathode, about twice the gas -> lower liquid level)
  \draw[thick] (2.8, 4.8) -- (2.8, 0.8) arc (180:360:0.7 and 0.2) -- (4.2, 4.8);
  % Right tube liquid level (lower liquid = more gas)
  \dotregion{2.81}{0.8}{4.19}{1.5}

  % --- Gas bubbles ---
  \foreach \p in {(1.5, 1.9), (1.4, 2.1), (1.6, 2.3)}
    \draw[fill=white] \p circle (0.05);
  \foreach \p in {(3.5, 1.9), (3.4, 2.2), (3.6, 2.5), (3.5, 2.8)}
    \draw[fill=white] \p circle (0.05);

  % --- Circuit / Battery below ---
  \draw[wire] (1.5, -0.4) -- (1.5, -1.2) -- (0.8, -1.2);
  \draw[wire] (3.5, -0.4) -- (3.5, -1.2) -- (4.2, -1.2);

  % Battery symbol
  \draw[wire] (0.8, -0.8) -- (0.8, -1.6); % long thin
  \draw[wire] (0.5, -1.0) -- (0.5, -1.4); % short thick
  \draw[wire] (0.5, -1.2) -- (0.2, -1.2);
  \draw[wire] (0.8, -1.2) -- (1.1, -1.2);

  % Battery connections to the wires
  \draw[wire] (1.1, -1.2) -- (1.5, -1.2);
  \draw[wire] (4.2, -1.2) -- (3.5, -1.2);
  \draw[wire] (0.2, -1.2) -- (0.2, -2.0) -- (4.2, -2.0) -- (4.2, -1.2);

  \node at (0.3, -0.7) {$+$};
  \node at (0.9, -0.7) {$-$};

  % --- Labels ---
  % Gas X
  \node[align=center] at (1.5, 3.2) {gas X};
  \draw[-{Stealth[length=2mm]}] (1.5, 2.9) -- (1.5, 2.5);

  % Gas Y
  \node[align=center] at (3.5, 3.2) {gas Y};
  \draw[-{Stealth[length=2mm]}] (3.5, 2.9) -- (3.5, 1.8);

  % Anode and Cathode labels with pointer lines
  \draw[-{Stealth[length=2mm]}] (0.3, 1.2) -- (1.3, 1.2);
  \node[anchor=east] at (0.2, 1.2) {anode};

  \draw[-{Stealth[length=2mm]}] (4.7, 1.2) -- (3.7, 1.2);
  \node[anchor=west] at (4.8, 1.2) {cathode};

  % --- Caption ---
  \node at (2.5, -2.6) {Fig. 3.1};

\end{tikzpicture}

